import "./AdoptionList.css";
import AdoptionCard from "../AdoptionCard/AdoptionCard";
import AdoptionListHeader from "../AdoptionListHeader/AdoptionListHeader";
import AdoptionSearchBar from "../AdoptionSearchBar/AdoptionSearchBar";
import { useState } from "react";
const AdoptionList = () => {
  const [searchTerm, setSearchTerm] = useState("");

  const animals = [
    {
      id: 1,
      image: "https://via.placeholder.com/250",
      name: "Bella",
      details: "8 months old, Female",
      place: "New York Shelter",
    },
    {
      id: 2,
      image: "https://via.placeholder.com/250",
      name: "Charlie",
      details: "2 years old, Male",
      place: "California Shelter",
    },
    {
      id: 3,
      image: "https://via.placeholder.com/250",
      name: "Luna",
      details: "3 months old, Female",
      place: "Florida Shelter",
    },
    {
      id: 4,
      image: "https://via.placeholder.com/250",
      name: "Max",
      details: "1 year old, Female",
      place: "Texas Shelter",
    },
    {
      id: 5,
      image: "https://via.placeholder.com/250",
      name: "Daisy",
      details: "2 years old, Male",
      place: "Nevada Shelter",
    },
  ];

  // تصفية الحيوانات بناءً على searchTerm
  const filteredAnimals = animals.filter((animal) =>
    animal.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSearch = (event) => {
    setSearchTerm(event.target.value);
  };

  return (
    <div>
      <AdoptionListHeader />
      <AdoptionSearchBar searchTerm={searchTerm} handleSearch={handleSearch} />

      {filteredAnimals.map((animal) => (
        <div key={animal.id} className="col">
          <AdoptionCard
            image={animal.image}
            name={animal.name}
            details={animal.details}
            place={animal.place}
          />
        </div>
      ))}
    </div>
  );
};

export default AdoptionList;
